PAGE_NO = {u: i + 1 for i, (u, *_rest) in enumerate(PAGES)}


def render(retrieved):
    out = [f"<!-- source: multiple primary pages, wave 3 epi, re-read live 2026-10-17 by the Opus verifier | retrieved: {retrieved} | "
           "method per page below; sentences are verbatim quotes (typographic minus and >= signs normalised), not full page copies -->", ""]
    for i, (u, title, method, quotes) in enumerate(PAGES, 1):
        out += [f"[[page {i} | printed {i}]]", f"URL: {u}", f"TITLE: {title}", f"METHOD: {method}"]
        out += [f"> {q}" for q in quotes]
        out.append("")
    return "\n".join(out)
